using Ling.Filter.Generators.Helpers;
using Ling.Filter.Generators.Models;
using Ling.Filter.Helpers;

namespace Ling.Filter.Generators;

partial class FilterGenerator
{
    private static class Execute
    {
        public static string GenerateSource(FilterGenerationSpec spec)
        {
            var cb = new CodeBuilder("""
                // <auto-generated/>

                #pragma warning disable
                #nullable enable

                """);

            if (!string.IsNullOrEmpty(spec.Hierarchy.Namespace))
            {
                cb.AppendFormatLine("namespace {0}", spec.Hierarchy.Namespace);
                cb.OpenBrace();
            }

            foreach (var typeInfo in spec.Hierarchy.Hierarchy)
            {
                cb.AppendFormatLine("partial {0} {1}", typeInfo.DeclarationKeyword, typeInfo.QualifiedName);
                cb.OpenBrace();
            }

            var firstMember = true;
            foreach (var target in spec.Targets)
            {
                if (target.ImplementsFilterable)
                {
                    if (!target.HasUserToExpression)
                    {
                        if (!firstMember)
                        {
                            cb.AppendLine();
                        }

                        EmitToExpressionMethod(cb, target);
                        firstMember = false;
                    }

                    if (!target.HasUserApply)
                    {
                        if (!firstMember)
                        {
                            cb.AppendLine();
                        }

                        EmitApplyMethod(cb, target);
                        firstMember = false;
                    }
                }

                if (target.ImplementsSortable && !target.HasUserApplySort)
                {
                    if (!firstMember)
                    {
                        cb.AppendLine();
                    }

                    EmitApplySortMethod(cb, target);
                    firstMember = false;
                }
            }

            cb.CloseAllBraces();
            return cb.ToString();
        }

        private static void EmitToExpressionMethod(CodeBuilder cb, EntityTargetSpec target)
        {
            var exprType = $"global::System.Linq.Expressions.Expression<global::System.Func<{target.EntityFullName}, bool>>";

            cb.AppendLine("/// <inheritdoc/>");
            if (target.UseExplicitFilterInterface)
            {
                cb.AppendFormatLine(
                    "{0} global::Ling.Filter.IFilterable<{1}>.ToExpression() => To{2}Expression();",
                    exprType,
                    target.EntityFullName,
                    target.EntitySimpleName);
                cb.AppendLine();
                cb.AppendLine("/// <summary>");
                cb.AppendFormatLine("/// Builds a combined predicate expression for <see cref=\"{0}\"/>.", target.EntityFullName);
                cb.AppendLine("/// </summary>");
                cb.AppendFormatLine("public {0} To{1}Expression()", exprType, target.EntitySimpleName);
            }
            else
            {
                cb.AppendFormatLine("public {0} ToExpression()", exprType);
            }

            cb.OpenBrace();

            if (target.Rules.IsEmpty)
            {
                cb.AppendFormatLine("return global::Ling.Filter.Expressions.ExpressionCombiner.True<{0}>();", target.EntityFullName);
                cb.CloseBrace();
                return;
            }

            cb.AppendFormatLine("{0}? __predicate = null;", exprType);
            EmitRuleBlocks(cb, target, isQueryableMode: false);
            cb.AppendLine();
            cb.AppendFormatLine("return __predicate ?? global::Ling.Filter.Expressions.ExpressionCombiner.True<{0}>();", target.EntityFullName);
            cb.CloseBrace();
        }

        private static void EmitApplyMethod(CodeBuilder cb, EntityTargetSpec target)
        {
            var queryType = $"global::System.Linq.IQueryable<{target.EntityFullName}>";

            cb.AppendLine("/// <inheritdoc/>");
            cb.AppendFormatLine("public {0} Apply({0} query)", queryType);
            cb.OpenBrace();
            cb.AppendLine("if (query is null)");
            cb.OpenBrace();
            cb.AppendLine("throw new global::System.ArgumentNullException(nameof(query));");
            cb.CloseBrace();

            if (!target.Rules.IsEmpty)
            {
                cb.AppendLine();
                if (target.DefaultLogicValue == 1) // CombineLogic.Or
                {
                    var exprType = $"global::System.Linq.Expressions.Expression<global::System.Func<{target.EntityFullName}, bool>>";
                    cb.AppendFormatLine("{0}? __predicate = null;", exprType);
                    EmitRuleBlocks(cb, target, isQueryableMode: false);
                    cb.AppendLine();
                    cb.AppendLine("if (__predicate is not null)");
                    cb.OpenBrace();
                    cb.AppendLine("query = global::System.Linq.Queryable.Where(query, __predicate);");
                    cb.CloseBrace();
                }
                else
                {
                    EmitRuleBlocks(cb, target, isQueryableMode: true);
                }
            }

            cb.AppendLine();
            cb.AppendLine("return query;");
            cb.CloseBrace();
        }

        private static void EmitRuleBlocks(CodeBuilder cb, EntityTargetSpec target, bool isQueryableMode)
        {
            var exprType = $"global::System.Linq.Expressions.Expression<global::System.Func<{target.EntityFullName}, bool>>";
            var topCombiner = target.DefaultLogicValue == 1 ? "Or" : "And";
            var groupLogicMap = new Dictionary<string, int>(StringComparer.Ordinal);
            foreach (var grp in target.Groups)
            {
                groupLogicMap[grp.Name] = grp.CombineLogicValue;
            }

            // Declare group accumulators if any rule references a group
            var groupVars = new Dictionary<string, string>(StringComparer.Ordinal);
            var groupIdx = 0;
            foreach (var rule in target.Rules)
            {
                if (rule.GroupName is { } gName && !groupVars.ContainsKey(gName))
                {
                    var gVar = $"__grp{groupIdx++}";
                    groupVars[gName] = gVar;
                    cb.AppendFormatLine("{0}? {1} = null;", exprType, gVar);
                }
            }

            var ruleIndex = 0;
            foreach (var rule in target.Rules)
            {
                cb.AppendLine();
                EmitSingleRule(cb, target.EntityFullName, rule, ruleIndex++, isQueryableMode, topCombiner, groupVars, groupLogicMap);
            }

            foreach (var kvp in groupVars)
            {
                var gVar = kvp.Value;
                cb.AppendLine();
                cb.AppendFormatLine("if ({0} is not null)", gVar);
                cb.OpenBrace();
                if (isQueryableMode)
                {
                    cb.AppendFormatLine("query = global::System.Linq.Queryable.Where(query, {0});", gVar);
                }
                else
                {
                    cb.AppendFormatLine("__predicate = global::Ling.Filter.Expressions.ExpressionCombiner.{0}(__predicate, {1});", topCombiner, gVar);
                }

                cb.CloseBrace();
            }
        }

        private static void EmitAppendLambda(
            CodeBuilder cb,
            string entityFullName,
            string lambdaText,
            bool isQueryableMode,
            string topCombiner,
            string? groupName,
            Dictionary<string, string> groupVars,
            Dictionary<string, int> groupLogicMap)
        {
            if (groupName is not null && groupVars.TryGetValue(groupName, out var gVar))
            {
                var logic = groupLogicMap.TryGetValue(groupName, out var l) ? l : 1;
                var combinerMethod = logic == 0 ? "And" : "Or";
                cb.AppendFormatLine(
                    "{0} = global::Ling.Filter.Expressions.ExpressionCombiner.{1}<{2}>({0}, {3});",
                    gVar,
                    combinerMethod,
                    entityFullName,
                    lambdaText);
                return;
            }

            if (isQueryableMode)
            {
                cb.AppendFormatLine("query = global::System.Linq.Queryable.Where(query, {0});", lambdaText);
            }
            else
            {
                cb.AppendFormatLine(
                    "__predicate = global::Ling.Filter.Expressions.ExpressionCombiner.{0}<{1}>(__predicate, {2});",
                    topCombiner,
                    entityFullName,
                    lambdaText);
            }
        }

        private static void EmitSingleRule(
            CodeBuilder cb,
            string entityFullName,
            FilterRuleSpec rule,
            int idx,
            bool isQueryableMode,
            string topCombiner,
            Dictionary<string, string> groupVars,
            Dictionary<string, int> groupLogicMap)
        {
            switch (rule.Kind)
            {
                case FilterRuleKind.CustomMethod:
                {
                    var vCustom = $"__custom{idx}";
                    cb.AppendFormatLine("var {0} = this.{1}();", vCustom, rule.MemberName);
                    cb.AppendFormatLine("if ({0} is not null)", vCustom);
                    cb.OpenBrace();
                    EmitAppendLambda(cb, entityFullName, vCustom, isQueryableMode, topCombiner, rule.GroupName, groupVars, groupLogicMap);
                    cb.CloseBrace();
                    break;
                }

                case FilterRuleKind.String:
                {
                    var check = BuildStringCheckCondition($"this.{rule.MemberName}", rule.StringIgnorePolicy);
                    cb.AppendFormatLine("if ({0})", check);
                    cb.OpenBrace();
                    var vName = $"__v{idx}";
                    cb.AppendFormatLine("var {0} = {1};", vName, BuildStringLocalValue($"this.{rule.MemberName}", rule.TrimString, rule.CaseInsensitive));
                    var body = BuildStringPredicateBody("x", rule.TargetPath, vName, rule.StringMode, rule.CaseInsensitive);
                    EmitAppendLambda(cb, entityFullName, $"x => {body}", isQueryableMode, topCombiner, rule.GroupName, groupVars, groupLogicMap);
                    cb.CloseBrace();
                    break;
                }

                case FilterRuleKind.MultiField:
                {
                    var isStringMember = rule.MemberUnwrappedTypeFullName == "string";
                    var openGuard = isStringMember
                        ? BuildStringCheckCondition($"this.{rule.MemberName}", rule.StringIgnorePolicy)
                        : BuildScalarActivationGuard(rule);

                    if (openGuard is not null)
                    {
                        cb.AppendFormatLine("if ({0})", openGuard);
                        cb.OpenBrace();
                    }
                    else
                    {
                        cb.OpenBrace();
                    }

                    var vName = $"__v{idx}";
                    if (isStringMember)
                    {
                        cb.AppendFormatLine("var {0} = {1};", vName, BuildStringLocalValue($"this.{rule.MemberName}", rule.TrimString, rule.CaseInsensitive));
                    }
                    else
                    {
                        cb.AppendFormatLine("var {0} = {1};", vName, BuildScalarUnwrappedAccess(rule));
                    }

                    var subBodies = new List<string>(rule.MultiFieldPaths.Length);
                    var opSym = CompareOpSymbol(rule.CompareOp);
                    var isNegated = rule.CompareOp == 1;
                    foreach (var path in rule.MultiFieldPaths)
                    {
                        var sub = isStringMember
                            ? BuildStringPredicateBody("x", path, vName, rule.StringMode, rule.CaseInsensitive)
                            : BuildComparePredicateBody("x", path, vName, opSym, isNegated: isNegated);
                        subBodies.Add($"({sub})");
                    }

                    var joiner = rule.CombineLogicValue == 0 ? " && " : " || ";
                    var combinedBody = string.Join(joiner, subBodies);
                    EmitAppendLambda(cb, entityFullName, $"x => {combinedBody}", isQueryableMode, topCombiner, rule.GroupName, groupVars, groupLogicMap);
                    cb.CloseBrace();
                    break;
                }

                case FilterRuleKind.Compare:
                {
                    var guard = BuildScalarActivationGuard(rule);
                    if (guard is not null)
                    {
                        cb.AppendFormatLine("if ({0})", guard);
                        cb.OpenBrace();
                    }
                    else
                    {
                        cb.OpenBrace();
                    }

                    var vName = $"__v{idx}";
                    cb.AppendFormatLine("var {0} = {1};", vName, BuildScalarUnwrappedAccess(rule));
                    var opSym = CompareOpSymbol(rule.CompareOp);
                    var body = BuildComparePredicateBody("x", rule.TargetPath, vName, opSym, isNegated: rule.CompareOp == 1);
                    EmitAppendLambda(cb, entityFullName, $"x => {body}", isQueryableMode, topCombiner, rule.GroupName, groupVars, groupLogicMap);
                    cb.CloseBrace();
                    break;
                }

                case FilterRuleKind.Range:
                {
                    EmitRangeFilterRule(cb, entityFullName, rule, idx, isQueryableMode, topCombiner, groupVars, groupLogicMap);
                    break;
                }

                case FilterRuleKind.Date:
                {
                    var guard = BuildScalarActivationGuard(rule);
                    if (guard is not null)
                    {
                        cb.AppendFormatLine("if ({0})", guard);
                        cb.OpenBrace();
                    }
                    else
                    {
                        cb.OpenBrace();
                    }

                    var rawVar = $"__raw{idx}";
                    cb.AppendFormatLine("var {0} = {1};", rawVar, BuildScalarUnwrappedAccess(rule));

                    if (rule.DatePrecisionValue == 0) // DatePrecision.Exact
                    {
                        var opSym = CompareOpSymbol(rule.CompareOp);
                        var exactBody = BuildComparePredicateBody("x", rule.TargetPath, rawVar, opSym, isNegated: rule.CompareOp == 1);
                        EmitAppendLambda(cb, entityFullName, $"x => {exactBody}", isQueryableMode, topCombiner, rule.GroupName, groupVars, groupLogicMap);
                    }
                    else
                    {
                        var startVar = $"__start{idx}";
                        var endVar = $"__end{idx}";
                        var precisionEnumLiteral = $"(global::Ling.Filter.Annotations.DatePrecision){rule.DatePrecisionValue}";
                        var isTimeOnly = rule.DateKind == DateTypeKind.TimeOnly;
                        var helperMethod = isTimeOnly ? "GetTimeRange" : "GetRange";

                        cb.AppendFormatLine(
                            "var ({0}, {1}) = global::Ling.Filter.Expressions.DatePrecisionHelper.{2}({3}, {4});",
                            startVar,
                            endVar,
                            helperMethod,
                            rawVar,
                            precisionEnumLiteral);

                        var dateBody = BuildDatePrecisionPredicateBody("x", rule.TargetPath, startVar, endVar, rule.CompareOp, isTimeOnly);
                        EmitAppendLambda(cb, entityFullName, $"x => {dateBody}", isQueryableMode, topCombiner, rule.GroupName, groupVars, groupLogicMap);
                    }

                    cb.CloseBrace();
                    break;
                }

                case FilterRuleKind.In:
                case FilterRuleKind.NotIn:
                {
                    var vColl = $"__v{idx}";
                    EmitOpenCollectionCheck(cb, rule, vColl, out var closeDepth);
                    var isNotIn = rule.Kind == FilterRuleKind.NotIn;
                    var inBody = BuildContainmentPredicateBody("x", rule.TargetPath, vColl, rule.IsCollectionElementNullableValueType, isNotIn);
                    EmitAppendLambda(cb, entityFullName, $"x => {inBody}", isQueryableMode, topCombiner, rule.GroupName, groupVars, groupLogicMap);
                    for (var c = 0; c < closeDepth; c++)
                    {
                        cb.CloseBrace();
                    }

                    break;
                }

                case FilterRuleKind.Collection:
                {
                    EmitCollectionFilterRule(cb, entityFullName, rule, idx, isQueryableMode, topCombiner, groupVars, groupLogicMap);
                    break;
                }

                case FilterRuleKind.NullCheck:
                {
                    var vBool = $"__b{idx}";
                    if (rule.IsMemberNullableValueType)
                    {
                        cb.AppendFormatLine("if (this.{0}.HasValue)", rule.MemberName);
                        cb.OpenBrace();
                        cb.AppendFormatLine("var {0} = this.{1}.GetValueOrDefault();", vBool, rule.MemberName);
                    }
                    else
                    {
                        cb.OpenBrace();
                        cb.AppendFormatLine("var {0} = this.{1};", vBool, rule.MemberName);
                    }

                    var trueMeansNotNull = rule.NullBehaviorValue == 0;
                    var notNullBody = BuildNullStatePredicateBody("x", rule.TargetPath, checkNotNull: true);
                    var isNullBody = BuildNullStatePredicateBody("x", rule.TargetPath, checkNotNull: false);

                    cb.AppendFormatLine("if ({0})", vBool);
                    cb.OpenBrace();
                    EmitAppendLambda(cb, entityFullName, $"x => {(trueMeansNotNull ? notNullBody : isNullBody)}", isQueryableMode, topCombiner, rule.GroupName, groupVars, groupLogicMap);
                    cb.CloseBrace();
                    cb.AppendLine("else");
                    cb.OpenBrace();
                    EmitAppendLambda(cb, entityFullName, $"x => {(trueMeansNotNull ? isNullBody : notNullBody)}", isQueryableMode, topCombiner, rule.GroupName, groupVars, groupLogicMap);
                    cb.CloseBrace();

                    cb.CloseBrace();
                    break;
                }

                case FilterRuleKind.Flags:
                {
                    var underlying = rule.EnumUnderlyingTypeFullName ?? "int";
                    var maskVar = $"__mask{idx}";

                    if (rule.IsMemberNullableValueType)
                    {
                        cb.AppendFormatLine("if (this.{0}.HasValue)", rule.MemberName);
                        cb.OpenBrace();
                        cb.AppendFormatLine("var {0} = ({1})this.{2}.GetValueOrDefault();", maskVar, underlying, rule.MemberName);
                        if (rule.IgnoreDefaultValue)
                        {
                            cb.AppendFormatLine("if ({0} != 0)", maskVar);
                            cb.OpenBrace();
                        }
                    }
                    else
                    {
                        cb.OpenBrace();
                        cb.AppendFormatLine("var {0} = ({1})this.{2};", maskVar, underlying, rule.MemberName);
                        if (rule.IgnoreDefaultValue)
                        {
                            cb.AppendFormatLine("if ({0} != 0)", maskVar);
                            cb.OpenBrace();
                        }
                    }

                    var flagsBody = BuildFlagsPredicateBody("x", rule.TargetPath, maskVar, underlying, rule.FlagsModeValue);
                    EmitAppendLambda(cb, entityFullName, $"x => {flagsBody}", isQueryableMode, topCombiner, rule.GroupName, groupVars, groupLogicMap);

                    if (rule.IgnoreDefaultValue)
                    {
                        cb.CloseBrace();
                    }

                    cb.CloseBrace();
                    break;
                }
            }
        }

        private static void EmitRangeFilterRule(
            CodeBuilder cb,
            string entityFullName,
            FilterRuleSpec rule,
            int idx,
            bool isQueryableMode,
            string topCombiner,
            Dictionary<string, string> groupVars,
            Dictionary<string, int> groupLogicMap)
        {
            var rVar = $"__r{idx}";
            if (rule.IsMemberNullableValueType)
            {
                cb.AppendFormatLine("if (this.{0} is {{ HasValue: true }} {1})", rule.MemberName, rVar);
            }
            else
            {
                cb.AppendFormatLine("if (this.{0}.HasValue)", rule.MemberName);
            }

            cb.OpenBrace();
            if (!rule.IsMemberNullableValueType)
            {
                cb.AppendFormatLine("var {0} = this.{1};", rVar, rule.MemberName);
            }

            var hasDatePrecision = rule.DatePrecisionValue != 0;
            var isTimeOnly = rule.DateKind == DateTypeKind.TimeOnly;
            var helperMethod = isTimeOnly ? "GetTimeRange" : "GetRange";
            var precisionEnumLiteral = $"(global::Ling.Filter.Annotations.DatePrecision){rule.DatePrecisionValue}";

            string minOp;
            string maxOp;
            if (hasDatePrecision)
            {
                minOp = rule.MinInclusive ? ">=" : (isTimeOnly ? ">" : ">=");
                maxOp = rule.MaxInclusive ? (isTimeOnly ? "<=" : "<") : "<";
            }
            else
            {
                minOp = rule.MinInclusive ? ">=" : ">";
                maxOp = rule.MaxInclusive ? "<=" : "<";
            }

            var minVar = $"__min{idx}";
            var maxVar = $"__max{idx}";

            // Both Min and Max specified -> combine as a single AND predicate so grouping (e.g., OR group) stays atomic
            cb.AppendFormatLine("if ({0}.Min.HasValue && {0}.Max.HasValue)", rVar);
            cb.OpenBrace();
            EmitRangeBoundLocal(cb, rVar, "Min", minVar, hasDatePrecision, helperMethod, precisionEnumLiteral, useEndOfBucket: !rule.MinInclusive);
            EmitRangeBoundLocal(cb, rVar, "Max", maxVar, hasDatePrecision, helperMethod, precisionEnumLiteral, useEndOfBucket: rule.MaxInclusive);
            var minBodyBoth = BuildComparePredicateBody("x", rule.TargetPath, minVar, minOp, isNegated: false);
            var maxBodyBoth = BuildComparePredicateBody("x", rule.TargetPath, maxVar, maxOp, isNegated: false);
            EmitAppendLambda(cb, entityFullName, $"x => ({minBodyBoth}) && ({maxBodyBoth})", isQueryableMode, topCombiner, rule.GroupName, groupVars, groupLogicMap);
            cb.CloseBrace();

            cb.AppendFormatLine("else if ({0}.Min.HasValue)", rVar);
            cb.OpenBrace();
            EmitRangeBoundLocal(cb, rVar, "Min", minVar, hasDatePrecision, helperMethod, precisionEnumLiteral, useEndOfBucket: !rule.MinInclusive);
            var minBodyOnly = BuildComparePredicateBody("x", rule.TargetPath, minVar, minOp, isNegated: false);
            EmitAppendLambda(cb, entityFullName, $"x => {minBodyOnly}", isQueryableMode, topCombiner, rule.GroupName, groupVars, groupLogicMap);
            cb.CloseBrace();

            cb.AppendFormatLine("else if ({0}.Max.HasValue)", rVar);
            cb.OpenBrace();
            EmitRangeBoundLocal(cb, rVar, "Max", maxVar, hasDatePrecision, helperMethod, precisionEnumLiteral, useEndOfBucket: rule.MaxInclusive);
            var maxBodyOnly = BuildComparePredicateBody("x", rule.TargetPath, maxVar, maxOp, isNegated: false);
            EmitAppendLambda(cb, entityFullName, $"x => {maxBodyOnly}", isQueryableMode, topCombiner, rule.GroupName, groupVars, groupLogicMap);
            cb.CloseBrace();

            cb.CloseBrace();
        }

        private static void EmitRangeBoundLocal(
            CodeBuilder cb,
            string rangeVar,
            string boundProp,
            string localVar,
            bool hasDatePrecision,
            string helperMethod,
            string precisionEnumLiteral,
            bool useEndOfBucket)
        {
            if (!hasDatePrecision)
            {
                cb.AppendFormatLine("var {0} = {1}.{2}.GetValueOrDefault();", localVar, rangeVar, boundProp);
                return;
            }

            if (useEndOfBucket)
            {
                cb.AppendFormatLine(
                    "var (_, {0}) = global::Ling.Filter.Expressions.DatePrecisionHelper.{1}({2}.{3}.GetValueOrDefault(), {4});",
                    localVar,
                    helperMethod,
                    rangeVar,
                    boundProp,
                    precisionEnumLiteral);
            }
            else
            {
                cb.AppendFormatLine(
                    "var ({0}, _) = global::Ling.Filter.Expressions.DatePrecisionHelper.{1}({2}.{3}.GetValueOrDefault(), {4});",
                    localVar,
                    helperMethod,
                    rangeVar,
                    boundProp,
                    precisionEnumLiteral);
            }
        }

        private static void EmitCollectionFilterRule(
            CodeBuilder cb,
            string entityFullName,
            FilterRuleSpec rule,
            int idx,
            bool isQueryableMode,
            string topCombiner,
            Dictionary<string, string> groupVars,
            Dictionary<string, int> groupLogicMap)
        {
            var vName = $"__v{idx}";
            var closeDepth = 1;
            var isCollectionDto = rule.CollectionStorageKind != 0;
            var isStringDto = !isCollectionDto && rule.MemberUnwrappedTypeFullName == "string";

            if (isCollectionDto)
            {
                EmitOpenCollectionCheck(cb, rule, vName, out closeDepth);
            }
            else if (isStringDto)
            {
                var check = BuildStringCheckCondition($"this.{rule.MemberName}", rule.StringIgnorePolicy);
                cb.AppendFormatLine("if ({0})", check);
                cb.OpenBrace();
                cb.AppendFormatLine("var {0} = {1};", vName, BuildStringLocalValue($"this.{rule.MemberName}", rule.TrimString, rule.CaseInsensitive));
            }
            else
            {
                var guard = BuildScalarActivationGuard(rule);
                if (guard is not null)
                {
                    cb.AppendFormatLine("if ({0})", guard);
                    cb.OpenBrace();
                }
                else
                {
                    cb.OpenBrace();
                }

                cb.AppendFormatLine("var {0} = {1};", vName, BuildScalarUnwrappedAccess(rule));
            }

            // Build outer navigation access up to the collection property (guarding single-reference hops before the collection)
            var (navGuard, collAccess) = BuildPathAccessAndGuard("x", rule.TargetPath);
            var itemParam = "__i";
            string itemPredicate;

            if (rule.ElementSubPath is { } subPath)
            {
                if (isCollectionDto)
                {
                    itemPredicate = BuildContainmentPredicateBody(itemParam, subPath, vName, rule.IsCollectionElementNullableValueType, isNotIn: false);
                }
                else if (isStringDto)
                {
                    itemPredicate = BuildStringPredicateBody(itemParam, subPath, vName, rule.StringMode, rule.CaseInsensitive);
                }
                else
                {
                    itemPredicate = BuildComparePredicateBody(itemParam, subPath, vName, CompareOpSymbol(rule.CompareOp), isNegated: rule.CompareOp == 1);
                }
            }
            else
            {
                // Primitive/scalar collection element (e.g., List<string> Tags)
                if (isCollectionDto)
                {
                    itemPredicate = $"global::System.Linq.Enumerable.Contains({vName}, {itemParam})";
                }
                else if (isStringDto)
                {
                    itemPredicate = BuildDirectStringElementPredicate(itemParam, vName, rule.StringMode, rule.CaseInsensitive);
                }
                else
                {
                    itemPredicate = $"{itemParam} {CompareOpSymbol(rule.CompareOp)} {vName}";
                }
            }

            var quantifierCall = rule.QuantifierValue switch
            {
                1 => $"global::System.Linq.Enumerable.All({collAccess}, {itemParam} => {itemPredicate})",
                2 => $"!global::System.Linq.Enumerable.Any({collAccess}, {itemParam} => {itemPredicate})",
                _ => $"global::System.Linq.Enumerable.Any({collAccess}, {itemParam} => {itemPredicate})",
            };

            var fullLambdaBody = string.IsNullOrEmpty(navGuard)
                ? quantifierCall
                : rule.QuantifierValue == 2
                    ? $"{NegateNavGuard("x", rule.TargetPath)} || {quantifierCall}"
                    : $"{navGuard} && {quantifierCall}";

            EmitAppendLambda(cb, entityFullName, $"x => {fullLambdaBody}", isQueryableMode, topCombiner, rule.GroupName, groupVars, groupLogicMap);

            for (var c = 0; c < closeDepth; c++)
            {
                cb.CloseBrace();
            }
        }

        private static void EmitApplySortMethod(CodeBuilder cb, EntityTargetSpec target)
        {
            var queryType = $"global::System.Linq.IQueryable<{target.EntityFullName}>";

            cb.AppendLine("/// <inheritdoc/>");
            cb.AppendFormatLine("public {0} ApplySort({0} query)", queryType);
            cb.OpenBrace();
            cb.AppendLine("if (query is null)");
            cb.OpenBrace();
            cb.AppendLine("throw new global::System.ArgumentNullException(nameof(query));");
            cb.CloseBrace();
            cb.AppendLine();

            if (!target.SortFields.IsEmpty)
            {
                cb.AppendLine("if (!string.IsNullOrWhiteSpace(this.SortBy))");
                cb.OpenBrace();
                cb.AppendLine("switch (this.SortBy!.Trim().ToLowerInvariant())");
                cb.OpenBrace();

                foreach (var sf in target.SortFields)
                {
                    var (_, access) = BuildPathAccessAndGuard("x", sf.TargetPath);
                    cb.AppendFormatLine("case \"{0}\":", sf.SortKeyLowerInvariant.Replace("\\", "\\\\").Replace("\"", "\\\""));
                    cb.AppendFormatLine(
                        "    return this.SortDescending ? global::System.Linq.Queryable.OrderByDescending(query, x => {0}) : global::System.Linq.Queryable.OrderBy(query, x => {0});",
                        access);
                }

                cb.CloseBrace();
                cb.CloseBrace();
                cb.AppendLine();
            }

            if (!target.DefaultSorts.IsEmpty)
            {
                var firstSort = target.DefaultSorts[0];
                var (_, firstAccess) = BuildPathAccessAndGuard("x", firstSort.TargetPath);
                var firstOrderMethod = firstSort.Descending ? "OrderByDescending" : "OrderBy";

                if (target.DefaultSorts.Length == 1)
                {
                    cb.AppendFormatLine("return global::System.Linq.Queryable.{0}(query, x => {1});", firstOrderMethod, firstAccess);
                }
                else
                {
                    cb.AppendFormatLine("var __ordered = global::System.Linq.Queryable.{0}(query, x => {1});", firstOrderMethod, firstAccess);
                    for (var i = 1; i < target.DefaultSorts.Length; i++)
                    {
                        var nextSort = target.DefaultSorts[i];
                        var (_, nextAccess) = BuildPathAccessAndGuard("x", nextSort.TargetPath);
                        var thenMethod = nextSort.Descending ? "ThenByDescending" : "ThenBy";
                        cb.AppendFormatLine("__ordered = global::System.Linq.Queryable.{0}(__ordered, x => {1});", thenMethod, nextAccess);
                    }

                    cb.AppendLine("return __ordered;");
                }
            }
            else
            {
                cb.AppendLine("return query;");
            }

            cb.CloseBrace();
        }

        private static void EmitOpenCollectionCheck(CodeBuilder cb, FilterRuleSpec rule, string vColl, out int closeDepth)
        {
            switch (rule.CollectionStorageKind)
            {
                case 1: // Array
                    cb.AppendFormatLine("if (this.{0} is {{ Length: > 0 }} {1})", rule.MemberName, vColl);
                    cb.OpenBrace();
                    closeDepth = 1;
                    break;

                case 2: // Has .Count
                    cb.AppendFormatLine("if (this.{0} is {{ Count: > 0 }} {1})", rule.MemberName, vColl);
                    cb.OpenBrace();
                    closeDepth = 1;
                    break;

                default: // General IEnumerable<T> -> materialize once to T[]
                    cb.AppendFormatLine("if (this.{0} is not null)", rule.MemberName);
                    cb.OpenBrace();
                    cb.AppendFormatLine("var {0} = global::System.Linq.Enumerable.ToArray(this.{1});", vColl, rule.MemberName);
                    cb.AppendFormatLine("if ({0}.Length > 0)", vColl);
                    cb.OpenBrace();
                    closeDepth = 2;
                    break;
            }
        }

        private static string BuildStringCheckCondition(string propExpr, int ignorePolicy) => ignorePolicy switch
        {
            1 => $"!string.IsNullOrEmpty({propExpr})",
            2 => $"{propExpr} is not null",
            _ => $"!string.IsNullOrWhiteSpace({propExpr})",
        };

        private static string BuildStringLocalValue(string propExpr, bool trim, bool caseInsensitive)
        {
            var expr = $"{propExpr}!";
            if (trim)
            {
                expr += ".Trim()";
            }

            if (caseInsensitive)
            {
                expr += ".ToLower()";
            }

            return expr;
        }

        private static string? BuildScalarActivationGuard(FilterRuleSpec rule)
        {
            if (rule.IsMemberNullableValueType)
            {
                return $"this.{rule.MemberName}.HasValue";
            }

            if (rule.IsMemberReferenceType)
            {
                return $"this.{rule.MemberName} is not null";
            }

            if (rule.IgnoreDefaultValue)
            {
                return $"!global::System.Collections.Generic.EqualityComparer<{rule.MemberTypeFullName}>.Default.Equals(this.{rule.MemberName}, default)";
            }

            return null;
        }

        private static string BuildScalarUnwrappedAccess(FilterRuleSpec rule)
        {
            return rule.IsMemberNullableValueType
                ? $"this.{rule.MemberName}.GetValueOrDefault()"
                : $"this.{rule.MemberName}";
        }

        private static (string Guard, string LeafAccess) BuildPathAccessAndGuard(string rootParam, PropertyPathSpec path)
        {
            var guards = new List<string>();
            var current = rootParam;

            for (var i = 0; i < path.Segments.Length; i++)
            {
                var seg = path.Segments[i];
                current = $"{current}.{seg.PropertyName}";

                if (i < path.Segments.Length - 1)
                {
                    if (seg.IsReferenceType)
                    {
                        guards.Add($"{current} != null");
                    }
                    else if (seg.IsNullableValueType)
                    {
                        guards.Add($"{current}.HasValue");
                        current = $"{current}.Value";
                    }
                }
            }

            return (string.Join(" && ", guards), current);
        }

        private static string NegateNavGuard(string rootParam, PropertyPathSpec path)
        {
            var negs = new List<string>();
            var current = rootParam;

            for (var i = 0; i < path.Segments.Length - 1; i++)
            {
                var seg = path.Segments[i];
                current = $"{current}.{seg.PropertyName}";
                if (seg.IsReferenceType)
                {
                    negs.Add($"{current} == null");
                }
                else if (seg.IsNullableValueType)
                {
                    negs.Add($"!{current}.HasValue");
                    current = $"{current}.Value";
                }
            }

            return string.Join(" || ", negs);
        }

        private static string BuildStringPredicateBody(
            string rootParam,
            PropertyPathSpec path,
            string vVar,
            int mode,
            bool caseInsensitive)
        {
            var (navGuard, leaf) = BuildPathAccessAndGuard(rootParam, path);
            var strTarget = caseInsensitive ? $"{leaf}.ToLower()" : leaf;

            switch (mode)
            {
                case 0: // Equals
                {
                    var core = caseInsensitive ? $"{leaf} != null && {strTarget} == {vVar}" : $"{leaf} == {vVar}";
                    return string.IsNullOrEmpty(navGuard) ? core : $"{navGuard} && {core}";
                }

                case 1: // NotEquals
                {
                    var core = caseInsensitive ? $"{leaf} == null || {strTarget} != {vVar}" : $"{leaf} != {vVar}";
                    return string.IsNullOrEmpty(navGuard)
                        ? core
                        : $"{NegateNavGuard(rootParam, path)} || ({core})";
                }

                case 2: // Contains
                {
                    var core = $"{leaf} != null && {strTarget}.Contains({vVar})";
                    return string.IsNullOrEmpty(navGuard) ? core : $"{navGuard} && {core}";
                }

                case 3: // NotContains
                {
                    var core = $"{leaf} == null || !{strTarget}.Contains({vVar})";
                    return string.IsNullOrEmpty(navGuard)
                        ? core
                        : $"{NegateNavGuard(rootParam, path)} || {core}";
                }

                case 4: // StartsWith
                {
                    var core = $"{leaf} != null && {strTarget}.StartsWith({vVar})";
                    return string.IsNullOrEmpty(navGuard) ? core : $"{navGuard} && {core}";
                }

                case 5: // EndsWith
                {
                    var core = $"{leaf} != null && {strTarget}.EndsWith({vVar})";
                    return string.IsNullOrEmpty(navGuard) ? core : $"{navGuard} && {core}";
                }

                default:
                    return $"{leaf} == {vVar}";
            }
        }

        private static string BuildDirectStringElementPredicate(string itemParam, string vVar, int mode, bool caseInsensitive)
        {
            var strTarget = caseInsensitive ? $"{itemParam}.ToLower()" : itemParam;
            return mode switch
            {
                0 => caseInsensitive ? $"{itemParam} != null && {strTarget} == {vVar}" : $"{itemParam} == {vVar}",
                1 => caseInsensitive ? $"{itemParam} == null || {strTarget} != {vVar}" : $"{itemParam} != {vVar}",
                2 => $"{itemParam} != null && {strTarget}.Contains({vVar})",
                3 => $"{itemParam} == null || !{strTarget}.Contains({vVar})",
                4 => $"{itemParam} != null && {strTarget}.StartsWith({vVar})",
                5 => $"{itemParam} != null && {strTarget}.EndsWith({vVar})",
                _ => $"{itemParam} == {vVar}",
            };
        }

        private static string BuildComparePredicateBody(
            string rootParam,
            PropertyPathSpec path,
            string vVar,
            string opSym,
            bool isNegated)
        {
            var (navGuard, leaf) = BuildPathAccessAndGuard(rootParam, path);
            var core = $"{leaf} {opSym} {vVar}";

            if (string.IsNullOrEmpty(navGuard))
            {
                return core;
            }

            return isNegated
                ? $"{NegateNavGuard(rootParam, path)} || {core}"
                : $"{navGuard} && {core}";
        }

        private static string BuildDatePrecisionPredicateBody(
            string rootParam,
            PropertyPathSpec path,
            string startVar,
            string endVar,
            int compareOp,
            bool isTimeOnlyInclusiveEnd)
        {
            var (navGuard, leaf) = BuildPathAccessAndGuard(rootParam, path);
            var leafSeg = path.Segments[^1];
            var upperInOp = isTimeOnlyInclusiveEnd ? "<=" : "<";
            var upperOutOp = isTimeOnlyInclusiveEnd ? ">" : ">=";

            string core = compareOp switch
            {
                0 => $"{leaf} >= {startVar} && {leaf} {upperInOp} {endVar}", // Equal (same bucket)
                1 => leafSeg.IsNullableValueType
                    ? $"!{leaf}.HasValue || {leaf} < {startVar} || {leaf} {upperOutOp} {endVar}"
                    : $"{leaf} < {startVar} || {leaf} {upperOutOp} {endVar}",
                2 => $"{leaf} {upperOutOp} {endVar}",                        // GreaterThan (after bucket)
                3 => $"{leaf} >= {startVar}",                                // GreaterThanOrEqual (from start of bucket)
                4 => $"{leaf} < {startVar}",                                 // LessThan (before start of bucket)
                5 => $"{leaf} {upperInOp} {endVar}",                         // LessThanOrEqual (through end of bucket)
                _ => $"{leaf} >= {startVar} && {leaf} {upperInOp} {endVar}",
            };

            if (string.IsNullOrEmpty(navGuard))
            {
                return core;
            }

            return compareOp == 1
                ? $"{NegateNavGuard(rootParam, path)} || ({core})"
                : $"{navGuard} && ({core})";
        }

        private static string BuildContainmentPredicateBody(
            string rootParam,
            PropertyPathSpec path,
            string vColl,
            bool isCollectionElementNullableValueType,
            bool isNotIn)
        {
            var (navGuard, leaf) = BuildPathAccessAndGuard(rootParam, path);
            var leafSeg = path.Segments[^1];

            string containsExpr;
            if (leafSeg.IsNullableValueType && !isCollectionElementNullableValueType)
            {
                // Target is Nullable<T> (e.g., int?) while collection element is T (e.g., int[])
                containsExpr = isNotIn
                    ? $"!{leaf}.HasValue || !global::System.Linq.Enumerable.Contains({vColl}, {leaf}.Value)"
                    : $"{leaf}.HasValue && global::System.Linq.Enumerable.Contains({vColl}, {leaf}.Value)";
            }
            else if (!leafSeg.IsNullableValueType && isCollectionElementNullableValueType)
            {
                // Target is T while collection element is Nullable<T> (e.g., int?[])
                var castedTarget = $"({leafSeg.FullyQualifiedTypeName}?){leaf}";
                containsExpr = isNotIn
                    ? $"!global::System.Linq.Enumerable.Contains({vColl}, {castedTarget})"
                    : $"global::System.Linq.Enumerable.Contains({vColl}, {castedTarget})";
            }
            else
            {
                containsExpr = isNotIn
                    ? $"!global::System.Linq.Enumerable.Contains({vColl}, {leaf})"
                    : $"global::System.Linq.Enumerable.Contains({vColl}, {leaf})";
            }

            if (string.IsNullOrEmpty(navGuard))
            {
                return containsExpr;
            }

            return isNotIn
                ? $"{NegateNavGuard(rootParam, path)} || ({containsExpr})"
                : $"{navGuard} && ({containsExpr})";
        }

        private static string BuildNullStatePredicateBody(string rootParam, PropertyPathSpec path, bool checkNotNull)
        {
            var (navGuard, leaf) = BuildPathAccessAndGuard(rootParam, path);
            var core = checkNotNull ? $"{leaf} != null" : $"{leaf} == null";

            if (string.IsNullOrEmpty(navGuard))
            {
                return core;
            }

            return checkNotNull
                ? $"{navGuard} && {core}"
                : $"{NegateNavGuard(rootParam, path)} || {core}";
        }

        private static string BuildFlagsPredicateBody(
            string rootParam,
            PropertyPathSpec path,
            string maskVar,
            string underlyingType,
            int flagsMode)
        {
            var (navGuard, leaf) = BuildPathAccessAndGuard(rootParam, path);
            var leafSeg = path.Segments[^1];
            var enumExpr = leafSeg.IsNullableValueType ? $"{leaf}.Value" : leaf;
            var bitExpr = flagsMode switch
            {
                1 => $"((({underlyingType}){enumExpr} & {maskVar}) != 0)",           // HasAny
                2 => $"(({underlyingType}){enumExpr} == {maskVar})",                // Exact
                3 => $"((({underlyingType}){enumExpr} & {maskVar}) == 0)",          // HasNone
                _ => $"((({underlyingType}){enumExpr} & {maskVar}) == {maskVar})",  // HasAll
            };

            var core = leafSeg.IsNullableValueType ? $"{leaf}.HasValue && {bitExpr}" : bitExpr;
            return string.IsNullOrEmpty(navGuard) ? core : $"{navGuard} && {core}";
        }

        private static string CompareOpSymbol(int op) => op switch
        {
            1 => "!=",
            2 => ">",
            3 => ">=",
            4 => "<",
            5 => "<=",
            _ => "==",
        };
    }
}
